window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8a9b74d6fd0ecb1e"]={"versions": [{"id": "FIG-8a9b74d6fd0ecb1e", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines algorithmischen Einzelschritts der Prüffunktion innerhalb des AUTOSAR E2E-Protokolls (Profile 11). Das Diagramm beschreibt den internen Ablaufschritt „Read CRC“ der Funktion <code>E2E_P11Check()</code>, eingebettet in die AUTOSAR-Laufzeitumgebung zur Verifikation der Datenintegrität empfangener E2E-geschützter Kommunikationsdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext / Entität</strong>: <code>E2E_P11Check()</code> mit Symbol für Unteraktivität/Dekompensation.\n</li><li><strong>Eingangsdaten / Konfiguration</strong>: <code>Data</code> (Array bzw. Zeiger auf die empfangenen Nutz- und Steuerbytes), <code>Config-&gt;CRCOffset</code> (Konfigurationsparameter für den bitweisen Offset der CRC im Datenstrom).\n</li><li><strong>Lokale Variable</strong>: <code>ReceivedCRC</code> (Speicherziel für das extrahierte CRC-Byte).\n</li><li><strong>Knotenelemente</strong>: Initialer Startknoten (ausgefüllter Kreis), ein Aktionsknoten („Copy byte Data[Config-&gt;CRCOffset/8] to local variable ReceivedCRC“), finaler Aktivitätsendknoten (Bullauge).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Unteraktivität beginnt am Startknoten nach Aufruf des Teilschritts innerhalb von <code>E2E_P11Check()</code>.\n</li><li>Übergang zum Aktionsknoten: Das Datenbyte an der durch <code>Config-&gt;CRCOffset / 8</code> berechneten Byte-Position des Puffers <code>Data</code> wird ausgelesen und in die lokale Variable <code>ReceivedCRC</code> kopiert.\n</li><li>Nach Abschluss der Zuweisung führt der Kontrollfluss direkt zum Aktivitätsendknoten, womit der Teilschritt abgeschlossen ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der dargestellte Schritt ist normativer Bestandteil der Anforderung <code>[PRS_E2E_00519]</code>. Implementierungen von E2E Profile 11 müssen sicherstellen, dass <code>Config-&gt;CRCOffset</code> ein ganzzahliges Vielfaches von 8 Bits darstellt bzw. die Byte-Adressierung über <code>Config-&gt;CRCOffset / 8</code> exakt die Position der Prüfsumme im Datenpuffer referenziert. Die extrahierte Prüfsumme <code>ReceivedCRC</code> dient den nachfolgenden Schritten von <code>E2E_P11Check()</code> zum Abgleich gegen die über die Nutzdaten neu berechnete CRC.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-23eefd16f8006c03", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines algorithmischen Einzelschritts der Prüffunktion innerhalb des AUTOSAR E2E-Protokolls (Profile 11). Das Diagramm beschreibt den internen Ablaufschritt „Read CRC“ der Funktion <code>E2E_P11Check()</code>, eingebettet in die AUTOSAR-Laufzeitumgebung zur Verifikation der Datenintegrität empfangener E2E-geschützter Kommunikationsdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext / Entität</strong>: <code>E2E_P11Check()</code> mit Symbol für Unteraktivität/Dekompensation.\n</li><li><strong>Eingangsdaten / Konfiguration</strong>: <code>Data</code> (Array bzw. Zeiger auf die empfangenen Nutz- und Steuerbytes), <code>Config-&gt;CRCOffset</code> (Konfigurationsparameter für den bitweisen Offset der CRC im Datenstrom).\n</li><li><strong>Lokale Variable</strong>: <code>ReceivedCRC</code> (Speicherziel für das extrahierte CRC-Byte).\n</li><li><strong>Knotenelemente</strong>: Initialer Startknoten (ausgefüllter Kreis), ein Aktionsknoten („Copy byte Data[Config-&gt;CRCOffset/8] to local variable ReceivedCRC“), finaler Aktivitätsendknoten (Bullauge).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Unteraktivität beginnt am Startknoten nach Aufruf des Teilschritts innerhalb von <code>E2E_P11Check()</code>.\n</li><li>Übergang zum Aktionsknoten: Das Datenbyte an der durch <code>Config-&gt;CRCOffset / 8</code> berechneten Byte-Position des Puffers <code>Data</code> wird ausgelesen und in die lokale Variable <code>ReceivedCRC</code> kopiert.\n</li><li>Nach Abschluss der Zuweisung führt der Kontrollfluss direkt zum Aktivitätsendknoten, womit der Teilschritt abgeschlossen ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der dargestellte Schritt ist normativer Bestandteil der Anforderung <code>[PRS_E2E_00519]</code>. Implementierungen von E2E Profile 11 müssen sicherstellen, dass <code>Config-&gt;CRCOffset</code> ein ganzzahliges Vielfaches von 8 Bits darstellt bzw. die Byte-Adressierung über <code>Config-&gt;CRCOffset / 8</code> exakt die Position der Prüfsumme im Datenpuffer referenziert. Die extrahierte Prüfsumme <code>ReceivedCRC</code> dient den nachfolgenden Schritten von <code>E2E_P11Check()</code> zum Abgleich gegen die über die Nutzdaten neu berechnete CRC.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-47d572052f9af51f", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines algorithmischen Einzelschritts der Prüffunktion innerhalb des AUTOSAR E2E-Protokolls (Profile 11). Das Diagramm beschreibt den internen Ablaufschritt „Read CRC“ der Funktion <code>E2E_P11Check()</code>, eingebettet in die AUTOSAR-Laufzeitumgebung zur Verifikation der Datenintegrität empfangener E2E-geschützter Kommunikationsdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext / Entität</strong>: <code>E2E_P11Check()</code> mit Symbol für Unteraktivität/Dekompensation.\n</li><li><strong>Eingangsdaten / Konfiguration</strong>: <code>Data</code> (Array bzw. Zeiger auf die empfangenen Nutz- und Steuerbytes), <code>Config-&gt;CRCOffset</code> (Konfigurationsparameter für den bitweisen Offset der CRC im Datenstrom).\n</li><li><strong>Lokale Variable</strong>: <code>ReceivedCRC</code> (Speicherziel für das extrahierte CRC-Byte).\n</li><li><strong>Knotenelemente</strong>: Initialer Startknoten (ausgefüllter Kreis), ein Aktionsknoten („Copy byte Data[Config-&gt;CRCOffset/8] to local variable ReceivedCRC“), finaler Aktivitätsendknoten (Bullauge).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Unteraktivität beginnt am Startknoten nach Aufruf des Teilschritts innerhalb von <code>E2E_P11Check()</code>.\n</li><li>Übergang zum Aktionsknoten: Das Datenbyte an der durch <code>Config-&gt;CRCOffset / 8</code> berechneten Byte-Position des Puffers <code>Data</code> wird ausgelesen und in die lokale Variable <code>ReceivedCRC</code> kopiert.\n</li><li>Nach Abschluss der Zuweisung führt der Kontrollfluss direkt zum Aktivitätsendknoten, womit der Teilschritt abgeschlossen ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der dargestellte Schritt ist normativer Bestandteil der Anforderung <code>[PRS_E2E_00519]</code>. Implementierungen von E2E Profile 11 müssen sicherstellen, dass <code>Config-&gt;CRCOffset</code> ein ganzzahliges Vielfaches von 8 Bits darstellt bzw. die Byte-Adressierung über <code>Config-&gt;CRCOffset / 8</code> exakt die Position der Prüfsumme im Datenpuffer referenziert. Die extrahierte Prüfsumme <code>ReceivedCRC</code> dient den nachfolgenden Schritten von <code>E2E_P11Check()</code> zum Abgleich gegen die über die Nutzdaten neu berechnete CRC.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8a9b74d6fd0ecb1e", "to": "FIG-23eefd16f8006c03", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-23eefd16f8006c03", "to": "FIG-47d572052f9af51f", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
